var e={"guide.intro":`带有为你编写示例的 Harness 导览。`,"guide.case.new":`这里一切都是新的：指南从零开始，Opus 会针对你想做的事编写示例。`,"guide.case.import":`Harness 找到了你的导入内容：Opus 会利用你带来的内容（项目、记忆）编写示例。`,"guide.case.existing":`你已在使用 Harness：指南会用你自己的会话和智能体作为示例，并展示你还没试过的功能。`,"guide.resumeDesc":`你停在了第 {n} 步，共 {total} 步。`,"guide.resume":`从上次停下的地方继续`,"guide.restart":`重新开始`,"guide.level.beginner":`初学者`,"guide.level.beginnerDesc":`我刚接触 Claude 和 Harness。请用简单的示例一步步带我了解。`,"guide.level.intermediate":`中级`,"guide.level.intermediateDesc":`我已经在使用 Claude 或其他智能体。请用更深入的示例展示 Harness 的增强之处。`,"guide.notNow":`关闭，我不需要`,"guide.mode.full":`完整导览（约 5 分钟）`,"guide.mode.fullDesc":`全部内容：会话、分区和标签页、记忆、智能体、定时任务、手机、需要开启的页面。`,"guide.mode.partial":`部分导览（约 2 分钟）`,"guide.mode.partialDesc":`基础内容，外加你想使用的功能（已勾选推荐项）：`,"guide.use.automate":`自动化（智能体、定时任务、任务）`,"guide.use.phone":`手机和 Telegram`,"guide.use.code":`代码和 Git`,"guide.use.sites":`网站和服务器`,"guide.use.mail":`电子邮件`,"guide.use.team":`多人协作`,"guide.use.content":`文件、文档、媒体`,"guide.recommended":`推荐`,"guide.start":`开始`,"guide.pause":`暂停指南`,"guide.pauseShort":`暂停`,"guide.featureOff":`此页面已关闭。开启后即可进行这一步（设置 -> 功能 会再次将其关闭）。`,"guide.enable":`开启`,"guide.writing":`Opus 正在为你编写示例…`,"guide.failed":`这次没有示例。`,"guide.retry":`重试`,"guide.try":`试一试`,"guide.tryHint":`消息会进入一个新会话：先阅读，可按需修改，然后发送。指南会停靠在屏幕右边缘等你。`,"guide.finish":`完成`,"guide.dock":`指南 · 第 {n}/{total} 步`,"guide.continue":`继续`,"guide.later":`稍后（帮助 -> 入门指南）`,"guide.welcome.title":`欢迎使用 Harness Maxxing`,"guide.welcome.body":`Harness 在你自己的服务器上运行 Claude：它在真实的文件夹中工作，记住重要的事，并在你不在时继续工作。`,"guide.welcome.tip":`随时可以暂停：指南会停靠在屏幕右边缘，点击左下角的帮助 (?) 可重新打开。`,"guide.nav.title":`一切都在这个侧边栏中`,"guide.nav.body":`仪表盘、会话、文件、设置：所有页面都在这里。在手机上，左上角的 ☰ 会打开同样的菜单。`,"guide.nav.tip":`拖动页面可重新排序；按 G 再按一个字母可跳转到对应页面（G S = 会话）。`,"guide.tree.title":`项目、主题、会话`,"guide.tree.body":`你的工作按项目整理，每个项目又分为多个主题。主题是 Harness 工作所在的文件夹，拥有自己的记忆；其中的每次对话就是一个会话。`,"guide.tree.tip":`将会话拖到另一个主题上即可移动；其 … 菜单（或右键）可将其加入收藏。`,"guide.first-prompt.title":`你的第一个请求`,"guide.first-prompt.body":`会话是在某个主题中与 Claude 的对话。它会在其中写入真实的文件，你一键即可打开。`,"guide.first-prompt.tip":`将文件拖到消息框即可附加，也可以用麦克风语音输入。Claude 工作时发送的消息会排队等待。`,"guide.memory.title":`Harness 会记住`,"guide.memory.body":`每个主题都有一个 memory.md，其所有会话都会读取，另外还有项目和全局的记忆。你可以在这里查看并编辑全部记忆。`,"guide.memory.tip":`在会话中说“记住……”：这条信息会存入合适的记忆，下一个会话就会知道。`,"guide.view-switch.title":`分区或标签页`,"guide.view-switch.body":`分区并排显示多个会话（列、网格）；标签页一次显示一个，其余以小标签显示。此按钮用于切换，亮起的即为当前生效的。`,"guide.view-switch.tip":`Alt+T 同样可以切换。在分区中，拖动会话的手柄可将其放到别处；你的选择会从电脑同步到手机。`,"guide.palette.title":`查找一切`,"guide.palette.body":`⌘K / Ctrl+K 可搜索文件、会话、主题、设置和操作。这是最快的导航方式。`,"guide.palette.tip":`输入要找内容的几个字母，甚至是某个设置的名称，然后按 Enter。`,"guide.agents.title":`智能体为你工作`,"guide.agents.body":`智能体是主题中的长期角色：它会自行启动（定时、电子邮件、Webhook、另一个智能体），并遵守每日预算。`,"guide.agents.tip":`无需填写表单：在会话中提出需要一个智能体，Harness 只会询问缺少的信息。在智能体页面一键即可关闭。`,"guide.agents-sessions.title":`智能体，会话视角`,"guide.agents-sessions.body":`智能体的每次运行都是其主题中的一个会话：打开它可查看做了什么、在其中回复，或在任意会话中交给它工作。`,"guide.agents-sessions.tip":`在消息框中输入 @ 可提及另一个会话或智能体；群组可将 2 到 6 个智能体与你放在同一个对话中。`,"guide.crons.title":`定时执行`,"guide.crons.body":`定时任务可以每天、每小时或在之后某个时间运行一次命令或提示词，并按需生成报告。`,"guide.crons.tip":`在会话中直接说“每天早上 8 点，……”或“10 分钟后提醒我”即可。`,"guide.tasks.title":`任务`,"guide.tasks.body":`你的待办看板，Harness 也会读取并更新它。`,"guide.tasks.tip":`在会话中问“今天有什么要做？”，即可为你读取看板。`,"guide.telegram.title":`用手机使用`,"guide.telegram.body":`关联 Telegram 机器人后，可以继续任意会话、发起新会话、发送语音消息和照片，并接收提醒。`,"guide.telegram.tip":`Harness 也可以安装为应用：iPhone 上选择 分享 -> 添加到主屏幕，Android 上使用浏览器菜单，并支持通知。`,"guide.code.title":`代码与 Git`,"guide.code.body":`Harness 在你的仓库中工作。每条回答下方的“更改”视图会显示该回合的 diff：可以撤销某个文件、提交、推送、发起拉取请求。`,"guide.code.tip":`“回退到此消息之前”（消息菜单中）会撤销某个回合所做的更改：你可以放心尝试任何事。`,"guide.sites.title":`网站与服务器`,"guide.sites.body":`Infra 会显示每个网站、数据库、存储桶、域名和服务器及其状态；Harness 会以标准方式在此服务器上上线内容。`,"guide.sites.tip":`在会话中问“X 在哪里？”或“我的网站正常吗？”：Harness 会实时检查。`,"guide.mail.title":`邮件`,"guide.mail.body":`你的邮箱都在 Harness 中：它会阅读、分类、归档并起草回复；未经你同意不会发出任何内容。`,"guide.mail.tip":`智能体可以拥有自己的邮箱，并设定允许回复的发件人。`,"guide.team.title":`与他人协作`,"guide.team.body":`团队：与联系人和群组聊天，并向他们分享会话或文件。`,"guide.team.tip":`Harness 可以替你给联系人写信，但只在你要求时才会这样做。`,"guide.content.title":`文件与文档`,"guide.content.body":`Harness 生成的每个文件（PDF、图片、视频、文档）都可以在这里打开和编辑；回复中的路径可以点击。`,"guide.content.tip":`在从会话中打开的文档里，选中一段文字并点击“评论”：会话会读取你的评论。`,"guide.tools.title":`给 Harness 装上双手`,"guide.tools.body":`有两个工具在你开启之前一直处于关闭状态。浏览器：这台服务器上的 Chromium，Harness 用它操作没有 API 的网站（登录、表单、仪表盘），你可以旁观并随时接管。设备：你自己的电脑或 Android 手机，需配合 Harness Link 应用使用。`,"guide.tools.tip":`两者你都可以随时停用：设置 -> 浏览器 和 设置 -> 设备 会显示 Harness 的操作，项目或主题也可以拒绝使用。`,"guide.tools.browser":`浏览器：Harness 在这台服务器上打开网站、登录并填写表单。`,"guide.tools.devices":`设备：添加后，Harness 可以查看并操控你的电脑或手机。`,"guide.safety.title":`保护你的工作`,"guide.safety.body":`备份会把你的记忆和工作区复制到私有的 GitHub 仓库：可以用来找回全部内容，或迁移到新服务器。`,"guide.safety.tip":`密钥和密码请放在 设置 -> 密钥 中，不要写在消息里：会话和脚本会从那里读取。`,"guide.features.title":`启用你需要的功能`,"guide.features.body":`可选页面（任务、智能体、邮件、Git、Infra、团队、浏览器、设备……）在需要之前保持关闭：在这里一键开启。`,"guide.features.tip":`设置 -> 外观 可更改颜色、字体和布局；仪表盘的“编辑布局”可移动其中的卡片。`,"guide.health.title":`服务器健康`,"guide.health.body":`当有事情需要留意时，这个圆点会变成橙色或红色：磁盘、内存、失败的任务、已停止的服务。`,"guide.health.tip":`点击它查看详情和解决办法；更新也会在这里提示。`,"guide.final.title":`一切就绪`,"guide.final.body":`为你挑选了一些后续步骤。指南仍保留在左下角的帮助 (?) 中。`,"guide.final.tip":`边做边学：交互式教程会带你完成真实的练习。`,"tour.step":`第 {n} 步，共 {total} 步`,"tour.next":`下一步`,"tour.back":`返回`,"tour.skip":`跳过导览`};export{e as default};